import{bV as e,aL as o,u as d,G as r}from"./chunks/framework.ExNI9tDi.js";const p=JSON.parse('{"title":"Api接口","description":"","frontmatter":{"date":"2026-08-06T22:22:34.000Z","title":"Api接口","permalink":"/pages/opencv","categories":["接口"]},"headers":[],"relativePath":"01.接口/50.高级接口/117.OpencvOps_图像处理/01.Api接口.md","filePath":"01.接口/50.高级接口/117.OpencvOps_图像处理/01.Api接口.md","lastUpdated":null}'),a={name:"01.接口/50.高级接口/117.OpencvOps_图像处理/01.Api接口.md"};function c(l,t,i,n,s,g){return o(),d("div",null,[...t[0]||(t[0]=[r('<h1 id="api接口" tabindex="-1">Api接口 <a class="header-anchor" href="#api接口" aria-label="Permalink to &quot;Api接口&quot;">​</a></h1><h2 id="模块简介" tabindex="-1">模块简介 <a class="header-anchor" href="#模块简介" aria-label="Permalink to &quot;模块简介&quot;">​</a></h2><p><code>OpencvOps</code> 提供常用图像预处理能力。</p><ul><li><strong>系统要求</strong>：Android 7.0+（minSdk 24）</li></ul><h2 id="功能概览" tabindex="-1">功能概览 <a class="header-anchor" href="#功能概览" aria-label="Permalink to &quot;功能概览&quot;">​</a></h2><ul><li><strong>统一转换</strong>：<code>bitmapToMat(bitmap)</code> —— Bitmap 转 Mat 句柄（入口）</li><li><strong>读取文件</strong>：<code>readResMat(path)</code> —— 从图片文件读取为 Mat</li><li><strong>尺寸查询</strong>：<code>getWidth(matId)</code> / <code>getHeight(matId)</code> —— 获取 Mat 宽高</li><li><strong>灰度处理</strong>：<code>matToGray(matId)</code> —— 彩色图转单通道灰度图</li><li><strong>二值化处理</strong>：<code>matThreshold(matId, thresh, maxval, type)</code> —— 固定阈值二值化</li><li><strong>双阈值二值化</strong>：<code>matDoubleThreshold(matId, lowThresh, highThresh, maxval)</code> —— 区间保留二值化</li><li><strong>自适应二值化</strong>：<code>matAdaptiveThreshold(matId, maxValue, adaptiveMethod, thresholdType, blockSize, c)</code> —— 局部自适应二值化</li><li><strong>颜色空间转换</strong>：<code>getHSV(matId, type)</code> / <code>getHLS(matId, type)</code> / <code>getBGR(matId, type)</code> —— 全图或单通道</li><li><strong>像素平均值</strong>：<code>getBGRAverage(matId, type)</code> —— 获取 BGR 各通道像素平均值</li><li><strong>边缘检测</strong>：<code>findCannys(matId, threshold1, threshold2, apertureSize, L2gradient)</code> —— Canny 边缘检测</li><li><strong>形状检测</strong>：<code>findLines</code> / <code>findCircles</code> / <code>findPolygons</code> —— 直线 / 圆 / 凸包形状检测</li><li><strong>凸包</strong>：<code>getConvexHull</code> / <code>isContourConvex</code></li><li><strong>轮廓处理</strong>：<code>getContours</code> / <code>getContoursRect</code> / <code>getContoursCircles</code> / <code>getContoursLength</code> / <code>getContoursArea</code> / <code>getContoursHierarchy</code> / <code>getContoursMoments</code></li><li><strong>形态学操作</strong>：<code>dilate</code> / <code>erode</code> / <code>open</code> / <code>close</code> / <code>topHat</code> / <code>blackHat</code> / <code>gradient</code> / <code>skeleton</code></li><li><strong>滤波 / 像素运算</strong>：<code>absDiff</code> / <code>bitwiseOr</code> / <code>medianBlur</code> / <code>gaussianBlur</code> / <code>blur</code> / <code>bilateral</code> / <code>filter2D</code></li><li><strong>颜色范围 / 掩膜</strong>：<code>inRange</code> / <code>copyTo</code></li><li><strong>区域操作</strong>：<code>cropMat</code>（裁剪） / <code>drawRect</code> / <code>drawRects</code>（画框） / <code>findImg</code>（模板匹配找图）</li><li><strong>梯度形状匹配</strong>：<code>loadYaml</code> / <code>matchGradientShape</code> / <code>releaseYaml</code> / <code>getYamlNames</code></li><li><strong>多边形检测</strong>：<code>detectPolygons</code></li><li><strong>几何变换</strong>：<code>warpPerspective</code>（透视变换）</li><li><strong>投影与计数</strong>：<code>projection</code> / <code>projectionValue</code>（行 / 列投影）/ <code>countNonZero</code> / <code>countNonZeroRect</code>（非零像素计数）</li><li><strong>保存</strong>：<code>saveMat(matId, path)</code> —— Mat 句柄保存为图片文件（自动创建父目录）</li><li><strong>回收</strong>：<code>recycle(matId)</code> / <code>clearMats()</code> —— 释放 Mat 池内存</li><li><strong>回收校验</strong>：<code>isRecycled(matId)</code> —— 判断 Mat 句柄是否已回收</li></ul><h2 id="文档拆分说明" tabindex="-1">文档拆分说明 <a class="header-anchor" href="#文档拆分说明" aria-label="Permalink to &quot;文档拆分说明&quot;">​</a></h2><p>OpencvOps 的接口数量较多，原单页文档已经拆为按能力分类的页面。/pages/opencv 保留为总览入口，旧链接不会失效；新增接口请优先放入对应分类页，只有跨分类的完整流程放入示例页。</p><h2 id="分类文档" tabindex="-1">分类文档 <a class="header-anchor" href="#分类文档" aria-label="Permalink to &quot;分类文档&quot;">​</a></h2><table tabindex="0"><thead><tr><th>分类</th><th>内容</th><th>页面</th></tr></thead><tbody><tr><td>基础转换与阈值颜色</td><td>Bitmap/Mat 转换、读取、尺寸、灰度、阈值、HSV/HLS/BGR</td><td><a href="./02.基础转换与阈值颜色.html">02.基础转换与阈值颜色</a></td></tr><tr><td>边缘轮廓与形状</td><td>Canny、直线、圆、多边形、凸包、轮廓统计</td><td><a href="./03.边缘轮廓与形状.html">03.边缘轮廓与形状</a></td></tr><tr><td>形态学滤波与掩膜</td><td>膨胀腐蚀、开闭运算、滤波、颜色范围、骨架</td><td><a href="./04.形态学滤波与掩膜.html">04.形态学滤波与掩膜</a></td></tr><tr><td>区域绘制与模板找图</td><td>裁剪、缩放、画框、模板匹配找图</td><td><a href="./20.区域绘制与模板找图.html">20.区域绘制与模板找图</a></td></tr><tr><td>梯度形状匹配与多边形检测</td><td>YAML 加载、梯度形状匹配、结果释放、多边形检测</td><td><a href="./25.梯度形状匹配与多边形检测.html">25.梯度形状匹配与多边形检测</a></td></tr><tr><td>几何投影与资源管理</td><td>透视变换、投影、非零计数、保存、回收</td><td><a href="./80.几何投影与资源管理.html">80.几何投影与资源管理</a></td></tr><tr><td>完整 Lua 示例与实践</td><td>完整链路、OOP 写法、性能优化、错误处理</td><td><a href="./90.完整Lua示例与实践.html">90.完整Lua示例与实践</a></td></tr></tbody></table><h2 id="新增接口文档约定" tabindex="-1">新增接口文档约定 <a class="header-anchor" href="#新增接口文档约定" aria-label="Permalink to &quot;新增接口文档约定&quot;">​</a></h2><p>每个新增公开方法至少补齐以下内容：</p><table tabindex="0"><thead><tr><th>项目</th><th>要求</th></tr></thead><tbody><tr><td>方法小节</td><td>使用 <code>#### methodName(args)</code>，参数必须和 Kotlin 公共签名一致</td></tr><tr><td>参数表</td><td>每个参数都写类型、是否必填、含义和边界值</td></tr><tr><td>返回值表</td><td>写清返回类型、成功值、失败值，JSON 字符串要说明字段结构</td></tr><tr><td>返回值示例</td><td>返回 JSON 或复杂字符串时必须给出示例；简单 <code>Boolean</code> / <code>String</code> 也建议写失败示例</td></tr><tr><td>Lua 示例</td><td>每个能力分类页至少保留可运行的最小示例；复杂方法单独给示例</td></tr><tr><td>注意事项</td><td>需要初始化、文件权限、坐标范围、Mat 回收、耗时行为时必须说明</td></tr></tbody></table><h2 id="api-接口索引" tabindex="-1">API 接口索引 <a class="header-anchor" href="#api-接口索引" aria-label="Permalink to &quot;API 接口索引&quot;">​</a></h2><ul><li><strong>统一转换</strong></li><li><strong>灰度处理</strong></li><li><strong>二值化处理</strong></li><li><strong>双阈值二值化</strong></li><li><strong>自适应二值化</strong></li><li><strong>颜色空间转换</strong></li><li><strong>边缘/轮廓检测</strong></li><li><strong>形状检测</strong></li><li><strong>凸包</strong></li><li><strong>轮廓处理</strong></li><li><strong>形态学操作</strong></li><li><strong>滤波</strong></li><li><strong>颜色范围 / 掩膜</strong></li><li><strong>图像区域操作</strong></li><li><strong>梯度形状匹配</strong></li><li><strong>几何变换</strong></li><li><strong>投影</strong></li><li><strong>保存 / 回收</strong></li></ul>',15)])])}const m=e(a,[["render",c]]);export{p as __pageData,m as default};
